import{_ as s,o as n,c as t,a2 as e}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Exploring RocksDB in RGW- How We Manage Tombstones - Sungjoon Koh & Ilsoo Byun, LINE Plus Corp","description":"","frontmatter":{"title":"Exploring RocksDB in RGW- How We Manage Tombstones - Sungjoon Koh & Ilsoo Byun, LINE Plus Corp","date":"2025-01-23T00:00:00.000Z","updated":"2025-01-24T00:00:00.000Z","tags":["Ceph","RocksDB","RGW","Tombstones","Performance Optimization"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Exploring_RocksDB_in_RGW_-_How_We_Manage_Tombstones_-_Sungjoon_Koh_Ilsoo_Byun_LINE_Plus_Corp.md","filePath":"posts/2025/Exploring_RocksDB_in_RGW_-_How_We_Manage_Tombstones_-_Sungjoon_Koh_Ilsoo_Byun_LINE_Plus_Corp.md","lastUpdated":1780459816000}'),r={name:"posts/2025/Exploring_RocksDB_in_RGW_-_How_We_Manage_Tombstones_-_Sungjoon_Koh_Ilsoo_Byun_LINE_Plus_Corp.md"};function a(l,o,i,_,g,c){return n(),t("div",null,[...o[0]||(o[0]=[e('<h3 id="会议纪要-ceph与rocksdb性能优化讨论" tabindex="-1">会议纪要：Ceph与RocksDB性能优化讨论 <a class="header-anchor" href="#会议纪要-ceph与rocksdb性能优化讨论" aria-label="Permalink to &quot;会议纪要：Ceph与RocksDB性能优化讨论&quot;">​</a></h3><p><strong>会议时间</strong>：下午<br><strong>会议主题</strong>：Ceph存储系统中RocksDB性能优化与Tombstone问题处理<br><strong>会议主持</strong>：Ishion（负责公司私有云存储服务）<br><strong>参会人员</strong>：Ceph研发团队成员、存储服务相关人员</p><h4 id="_1-会议背景" tabindex="-1">1. <strong>会议背景</strong> <a class="header-anchor" href="#_1-会议背景" aria-label="Permalink to &quot;1. **会议背景**&quot;">​</a></h4><ul><li><strong>公司存储服务</strong>：LINE Plus Corp 提供多种存储服务，包括块存储、文件存储和对象存储，主要基于Ceph分布式存储系统，管理超过30个集群，物理存储容量超过700PB。</li><li><strong>Ceph应用场景</strong>：Ceph不仅用于Line Messenger服务，还支持其他多种业务需求。</li></ul><h4 id="_2-rocksdb在ceph中的角色" tabindex="-1">2. <strong>RocksDB在Ceph中的角色</strong> <a class="header-anchor" href="#_2-rocksdb在ceph中的角色" aria-label="Permalink to &quot;2. **RocksDB在Ceph中的角色**&quot;">​</a></h4><ul><li><strong>RocksDB的作用</strong>：RocksDB作为Ceph内部元数据存储，负责存储RADOS对象的OMAP（Object Map）数据。OMAP通过RocksDB的键值对形式存储，支持点查询和范围查询。</li><li><strong>OMAP与RocksDB的关系</strong>：OMAP存储在RocksDB中，每个对象的OMAP键由对象ID和OMAP名称组成。范围查询操作在RGW（RADOS Gateway）中频繁使用，尤其是在列出桶内对象时。</li></ul><h4 id="_3-tombstone问题及其影响" tabindex="-1">3. <strong>Tombstone问题及其影响</strong> <a class="header-anchor" href="#_3-tombstone问题及其影响" aria-label="Permalink to &quot;3. **Tombstone问题及其影响**&quot;">​</a></h4><ul><li><strong>Tombstone的产生</strong>：当对象被删除时，RocksDB中的对应记录会被标记为删除（Tombstone），但不会立即物理删除。随着时间推移，这些Tombstone会积累在RocksDB的SST文件中，导致性能下降。</li><li><strong>Tombstone的影响</strong>：在执行范围查询时，RocksDB需要跳过大量Tombstone，导致CPU使用率飙升，OSD（对象存储守护进程）响应变慢，甚至完全无响应。</li><li><strong>实际案例</strong>：某次范围查询操作导致OSD CPU使用率达到100%，持续4小时，严重影响集群性能。</li></ul><h4 id="_4-tombstone问题的深入分析" tabindex="-1">4. <strong>Tombstone问题的深入分析</strong> <a class="header-anchor" href="#_4-tombstone问题的深入分析" aria-label="Permalink to &quot;4. **Tombstone问题的深入分析**&quot;">​</a></h4><ul><li><strong>RocksDB迭代机制</strong>：RocksDB在执行范围查询时，会遍历SST文件中的键值对。当遇到Tombstone时，RocksDB需要跳过这些删除标记，导致大量I/O和字符串解析操作，消耗大量CPU资源。</li><li><strong>Tombstone的分布</strong>：分析发现，大量Tombstone集中在少数几个前缀（Prefix）下，尤其是与桶索引相关的键值对。</li><li><strong>Tombstone的来源</strong>：Tombstone不仅来自对象删除操作，还可能来自多部分上传（Multipart Upload）操作，这些操作会在RocksDB中生成大量临时键值对，最终被删除。</li></ul><h4 id="_5-解决方案与优化措施" tabindex="-1">5. <strong>解决方案与优化措施</strong> <a class="header-anchor" href="#_5-解决方案与优化措施" aria-label="Permalink to &quot;5. **解决方案与优化措施**&quot;">​</a></h4><ul><li><strong>手动压缩（Compaction）</strong>：通过手动触发RocksDB的压缩操作，可以有效清理Tombstone，恢复OSD性能。但手动压缩无法持续解决问题，且可能影响写入性能。</li><li><strong>基于Skip Count的自动化压缩</strong>：通过监控RocksDB的Skip Count（跳过Tombstone的次数），可以预测哪些OSD可能面临性能问题，并自动触发压缩操作。</li><li><strong>前缀范围压缩（Prefix-based Compaction）</strong>：针对Tombstone集中在特定前缀下的问题，提出在桶索引级别进行压缩，而不是在整个OSD级别进行压缩。</li></ul><h4 id="_6-后续行动计划" tabindex="-1">6. <strong>后续行动计划</strong> <a class="header-anchor" href="#_6-后续行动计划" aria-label="Permalink to &quot;6. **后续行动计划**&quot;">​</a></h4><ul><li><strong>优化压缩策略</strong>：开发基于前缀的压缩功能，减少压缩操作的范围，避免对系统资源的过度消耗。</li><li><strong>社区讨论与贡献</strong>：将前缀范围压缩方案提交到Ceph社区，与社区开发者共同讨论和优化。</li><li><strong>持续监控与改进</strong>：继续监控RocksDB的性能指标，特别是Tombstone的分布和Skip Count，确保系统稳定运行。</li></ul>',14)])])}const u=s(r,[["render",a]]);export{p as __pageData,u as default};
